import json

n = 7

# Mark ONLY the main anti-diagonal (sum = n-1 = 6) with 1s
output_main_anti = []
for i in range(n):
    row_out = []
    for j in range(n):
        if i + j == n - 1:
            row_out.append(1)
        else:
            row_out.append(0)
    output_main_anti.append(row_out)

print("Main anti-diagonal only marked:")
for row in output_main_anti:
    print(row)
print(json.dumps({"action": "submit", "grid": output_main_anti}))

